I reproduced "unexpected EOF" with simple server and client:

```
$ go run client.go 
status code: 500
ReadAll: unexpected EOF
exit status 1
```

server.go
<Details>

```
package main

import (
	"log"
	"net/http"
	"time"
)

func main() {
	http.HandleFunc("/healthz", func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(500)
		go func() {
			time.Sleep(time.Second * 5)
			panic("disconnect")
		}()
		for {
			w.Write([]byte("foobar"))
			time.Sleep(time.Millisecond * 1)
		}
	})
	log.Fatal(http.ListenAndServe(":8080", nil))
}
```
</Details>

client.go
<Details>

```
package main

import (
	"fmt"
	"io/ioutil"
	"net/http"
	"os"
)

func main() {

	req, err := http.NewRequest(http.MethodGet, "http://localhost:8080/healthz", nil)
	if err != nil {
		fmt.Printf("NewRequest: %s\n", err)
		os.Exit(1)
	}

	res, err := http.DefaultClient.Do(req)
	if err != nil {
		fmt.Printf("Do: %s\n", err)
		os.Exit(1)
	}

	fmt.Printf("status code: %d\n", res.StatusCode)

	body, err := ioutil.ReadAll(res.Body)
	if err != nil {
		fmt.Printf("ReadAll: %s\n", err)
		os.Exit(1)
	}
	fmt.Printf("body: %s\n", body)
}

```

</Details>

It might be possible to reproduce this case in the e2e test by doing a similar thing (that is more elegant) in [agnhost/liveness](https://github.com/kubernetes/kubernetes/blob/master/test/images/agnhost/liveness/server.go)
